mapper.select:
select pro.P_Name as pName, pro.P_Code as pCode, pro.P_Approve_Budget as pApproveBudget, sec.Sec_Name as secName, sec.Sec_Bidding_Type as secBiddingType, sec.Sec_Place as secPlace, sec.Sec_Remark as secRemark, sec.Sec_Organize_Form as secOrganizeForm, sec.Sec_Type as secType, mn.* from Sec_Selection_Record_Multiple mn left join Pre_Project pro on pro.P_Id = mn.P_Id left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
